import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int[] a = new int[110];
        int i;
        for (i = 1; ; i++) {
            if (n == 1) {
                break;
            }
            int yushu = n % 2;
            n = n / 2;
            a[i] = yushu;
            if (n == 1) {
                i++;
                break;
            }
        }
        System.out.print(i);
        i--;
        for (; i >= 0; i--) {
            if (a[i] != 0) {
                System.out.print(" " + i);
            }
        }
        System.out.println();
    }
}

